@ Some portions generated by Claude Code (Opus 5).

@ zx_context.S -- Cortex-R52 -- the partition switch, at the exception
@                 boundary where it has to be assembly and nowhere else.
@
@ DESCRIPTION
@
@   Four routines and one contract.  The contract is that r0-r12 are SHARED
@   between Hyp mode and EL1 -- Hyp banks only SP, LR and SPSR -- so a guest's
@   general-purpose registers are destroyed by the first C instruction that
@   runs after an exception.  Everything else a partition owns is still in the
@   machine and can wait: its banked SPs and LRs, its EL1 system registers and
@   its whole EL1 MPU are all readable and writable from ordinary C at EL2.
@
@   So this file is deliberately SMALL.  It captures fifteen words, hands
@   over to C, and puts fifteen words back.  The twenty MPU regions that
@   dominate the switch's cost are a loop in zx_context.c, where a reader can
@   check them against the manifest they came from.
@
@ WHY A WINDOW BOUNDARY NEVER RETURNS TO C's CALLER
@
@   zx_el2_enter_partition is a ONE-WAY transfer, exactly as
@   zx_el2_run_payload is: it saves EL2's own resume context and ERETs.  A
@   window boundary is handled entirely inside the exception path -- save the
@   outgoing partition, ask C which one is next, restore it, ERET -- and the
@   hypervisor's C code never sees it.
@
@   That is not an optimisation.  A boundary that returned to C and was
@   re-entered would put a return, a dispatch and a call on the path whose
@   cost is the whole subject of this work, and it would make the
@   hypervisor's stack depth depend on how a guest happened to leave.  A
@   bounded switch cannot have either property.
@
@ WHY lr IS THE SCRATCH REGISTER
@
@   Every one of r0-r12 belongs to the guest at the instant the FIQ is taken,
@   and there is nowhere to put one before there is somewhere to put them
@   all.  LR_hyp is BANKED, and its live value -- EL2's own return address --
@   was already stored into zx_el2_resume_context by zx_el2_enter_partition
@   before the ERET.  So it is the one register that is both reachable and
@   free, and the capture below uses it to hold the context pointer while the
@   thirteen shared registers go out in one STM.
@
@ STACK DISCIPLINE
@
@   The boundary path pushes nothing.  SP_hyp is whatever EL2 left it at
@   before it ERETed into the guest, which is a valid Hyp stack pointer
@   inside zx_el2_enter_partition's frame, and the BL below runs on it at
@   one fixed depth however many boundaries a run takes.  A switch whose
@   stack grew per boundary would survive a demonstration and not a
@   deployment.  The one path that does push -- the capture from the trap
@   vector -- balances it explicitly, for the reason AR2 invariant 17 was
@   written: an unbalanced handler leaked bytes of a 1 KB stack per fault
@   during the Cortex-R52 Modules port work and presented as nothing at all
@   until the run got long.
@
@ NOTE ON SYNTAX
@
@   GNU assembler syntax, per CONTRIBUTING.md.

#include "zx_port.h"

    .syntax unified
    .arm

    .text
    .balign 4

/**************************************************************************/
/*  zx_el2_fiq_boundary -- HVBAR + 0x1C, the end of a partition's window.  */
/*                                                                        */
/*  THE ONE INTERRUPT A PARTITION CANNOT MASK.  With HCR.FMO set, PSTATE.F */
/*  is IGNORED at EL0 and EL1, so this vector is reached however a guest    */
/*  has set its own masks and whatever its kernel is doing with them.  A    */
/*  tick delivered as an IRQ could be deferred by any guest that disabled   */
/*  interrupts, which is exactly the property time partitioning must not    */
/*  concede -- and it is why the hypervisor's own timer goes in GIC Group 0 */
/*  rather than being injected.  See docs/decisions.md D24 and D25.        */
/*                                                                        */
/*  TWO THINGS ARE CHECKED BEFORE ANYTHING IS SAVED, and both are about    */
/*  writing a guest's registers into the wrong place:                      */
/*                                                                        */
/*    * that the exception came from EL1 and not from Hyp mode.  An FIQ    */
/*      taken while the HYPERVISOR runs would otherwise have EL2's own     */
/*      r0-r12 and ELR stored into the running partition's context block,  */
/*      and that partition would later be resumed inside the hypervisor.   */
/*      ZoneX keeps PSTATE.F set at EL2 so it cannot happen; it is checked */
/*      because the check is one comparison and being wrong is             */
/*      unrecoverable.                                                     */
/*    * that a partition is running at all.  Every other ZoneX image       */
/*      shares this vector table and leaves FMO clear, so for them an FIQ  */
/*      here is an exception nothing expected, and it is reported as one   */
/*      through the vector that already exists for it.                     */
/**************************************************************************/

    .global zx_el2_fiq_boundary
    .type   zx_el2_fiq_boundary, %function
zx_el2_fiq_boundary:

    @ Where was the core when this arrived?  SPSR_hyp holds the mode the
    @ exception was taken FROM.  lr is free here for the reason in the file
    @ header, and nothing has been disturbed yet.

    mrs     lr, SPSR_hyp
    and     lr, lr, #ZX_MODE_MASK
    cmp     lr, #ZX_MODE_HYP
    beq     zx_el2_vector_fiq                   @ report and stop

    ldr     lr, =zx_el2_current_context
    ldr     lr, [lr]
    cmp     lr, #0
    beq     zx_el2_vector_fiq                   @ no frame: unexpected

    @ THE FIFTEEN WORDS THAT CANNOT WAIT.  r0-r12 first, in one STM, before
    @ any of them is used for anything else; then the two Hyp-banked
    @ registers that say where EL1 was and in what state.

    stm     lr, {r0-r12}                        @ ZX_ASM_CTX_OFF_R0, 13 words
    mrs     r0, ELR_hyp
    str     r0, [lr, #ZX_ASM_CTX_OFF_ELR]
    mrs     r0, SPSR_hyp
    str     r0, [lr, #ZX_ASM_CTX_OFF_SPSR]

    @ C does the rest: the banked registers, the EL1 system registers, the
    @ whole EL1 MPU set, the time freeze, the region-set switch and the next
    @ deadline.  It returns the context to resume, or zero when the frame is
    @ over.

    bl      zx_el2_window_boundary

    cmp     r0, #0
    bne     zx_el2_context_resume

    @ The frame ended.  Go back to the hypervisor through the same path a
    @ fault takes, with the reason picked up from where C left it: this
    @ vector was never called, so there is no return value to carry it.

    ldr     r0, =zx_el2_frame_result
    ldr     r0, [r0]
    b       zx_el2_resume
    .size   zx_el2_fiq_boundary, . - zx_el2_fiq_boundary

/**************************************************************************/
/*  zx_el2_context_capture_from_stack                                     */
/*                                                                        */
/*  The same capture, for the paths where a guest left through the HYP     */
/*  TRAP vector -- a yield, or a fault -- rather than through the FIQ.     */
/*                                                                        */
/*  WHY THE GUEST'S r0 AND r1 COME OFF THE STACK.  The trap vector pushes  */
/*  them on entry, because two hypercall paths return to the guest         */
/*  transparently and must not have changed anything.  By the time control */
/*  reaches here those two registers hold the decoded syndrome instead,    */
/*  and the guest's real values are on the Hyp stack.  Storing what is in  */
/*  the registers would hand a partition a copy of its own exception       */
/*  syndrome and resume it with that -- a guest corrupted by the act of    */
/*  observing it, which is the hardest class of bug in this file to see.   */
/*                                                                        */
/*  Called with those two words still on the stack and leaves them there,  */
/*  so the caller's own "add sp, sp, #8" stays where it is and stays       */
/*  correct.  r2-r12 are still the guest's on every path that reaches      */
/*  here: the console path, which clobbers more, returns to the guest and  */
/*  never comes this way.                                                  */
/*                                                                        */
/*  Does nothing at all when no partition is running, which is every       */
/*  ZoneX image that launches a payload without a schedule.  Their yields  */
/*  and faults are unchanged by this file existing.                        */
/**************************************************************************/

    .global zx_el2_context_capture_from_stack
    .type   zx_el2_context_capture_from_stack, %function
zx_el2_context_capture_from_stack:

    @ r0 is saved because it is needed as scratch below; lr because BL put
    @ the return address in it and lr is the only register free to hold the
    @ context pointer.  Two words keeps SP 8-byte aligned, as AAPCS wants
    @ it, and the pop below balances this push on BOTH paths out.

    push    {r0, lr}

    ldr     lr, =zx_el2_current_context
    ldr     lr, [lr]
    cmp     lr, #0
    beq     zx_el2_capture_none

    stm     lr, {r0-r12}                        @ r0 and r1 are WRONG here

    @ The guest's real r0 and r1, from under this function's own frame:
    @ [sp] and [sp, #4] are what was just pushed, so the trap vector's two
    @ words are at +8 and +12.

    ldr     r0, [sp, #8]
    str     r0, [lr, #ZX_ASM_CTX_OFF_R0]
    ldr     r0, [sp, #12]
    str     r0, [lr, #(ZX_ASM_CTX_OFF_R0 + 4)]

    mrs     r0, ELR_hyp
    str     r0, [lr, #ZX_ASM_CTX_OFF_ELR]
    mrs     r0, SPSR_hyp
    str     r0, [lr, #ZX_ASM_CTX_OFF_SPSR]

zx_el2_capture_none:
    pop     {r0, lr}
    bx      lr
    .size   zx_el2_context_capture_from_stack, . - zx_el2_context_capture_from_stack

/**************************************************************************/
/*  zx_el2_enter_partition -- hand the core to a partition.               */
/*                                                                        */
/*    uint32_t zx_el2_enter_partition(ZX_GUEST_CONTEXT *context_ptr);     */
/*                                                                        */
/*  Saves EL2's own resume context -- the same one zx_el2_run_payload      */
/*  uses, and for the same reason -- and then restores the partition and    */
/*  ERETs.  It does not return through that ERET: control comes back        */
/*  through zx_el2_resume when a guest yields or faults, or when the        */
/*  boundary handler decides the frame is over.                            */
/*                                                                        */
/*  ONE RESUME SLOT, so this CANNOT NEST, and a time-partition schedule     */
/*  has no reason to: it enters one partition at a time, sequentially,      */
/*  and window boundaries never come back through here at all.             */
/**************************************************************************/

    .global zx_el2_enter_partition
    .type   zx_el2_enter_partition, %function
zx_el2_enter_partition:
    ldr     r2, =zx_el2_resume_context
    str     sp, [r2, #ZX_ASM_RESUME_OFF_SP]
    str     lr, [r2, #ZX_ASM_RESUME_OFF_LR]
    add     r3, r2, #ZX_ASM_RESUME_OFF_R4
    stmia   r3, {r4-r11}

    @ r0 already holds the context.  Branched rather than fallen through,
    @ so that the two routines can be read, moved or measured separately
    @ without a silent dependency on which one the assembler emits first.

    b       zx_el2_context_resume
    .size   zx_el2_enter_partition, . - zx_el2_enter_partition

/**************************************************************************/
/*  zx_el2_context_resume -- put fifteen words back and go.               */
/*                                                                        */
/*    void zx_el2_context_resume(ZX_GUEST_CONTEXT *context_ptr);          */
/*                                                                        */
/*  Does not return.                                                       */
/*                                                                        */
/*  ELR AND SPSR FIRST, THE THIRTEEN SHARED REGISTERS LAST, and the order  */
/*  is forced: writing ELR_hyp or SPSR_hyp needs a register to write from, */
/*  and after the LDM there is no register left that is not the guest's.   */
/*                                                                        */
/*  SPSR carries the guest's own interrupt masks back with it, exactly as  */
/*  they were when the window ended.  A switch that re-entered a partition */
/*  with masks of its own choosing would be changing a guest's state       */
/*  behind its back.  PSTATE.T is in there too, so a guest that was        */
/*  executing T32 comes back in T32 without this file having to know       */
/*  which -- the invariant that "SPSR.T must match the entry point's       */
/*  instruction set" is satisfied here by never having separated them.     */
/**************************************************************************/

    .global zx_el2_context_resume
    .type   zx_el2_context_resume, %function
zx_el2_context_resume:
    mov     lr, r0

    ldr     r0, [lr, #ZX_ASM_CTX_OFF_ELR]
    msr     ELR_hyp, r0
    ldr     r0, [lr, #ZX_ASM_CTX_OFF_SPSR]
    msr     SPSR_hyp, r0

    ldm     lr, {r0-r12}

    dsb
    isb
    eret
    .size   zx_el2_context_resume, . - zx_el2_context_resume
